// word-frequency (rust entry) -- count 3,000,000 picks from a 64-word
// vocabulary generated by a pinned integer LCG, then fold the counts into one
// deterministic checksum.
//
// Build:  rustc -O main.rs -o word-frequency.exe
// Run:    word-frequency.exe
//
// Same workload and same output in every language entry. This is the
// hash-map-shaped task: every pick is a string-keyed lookup + increment, and
// the final fold walks the vocabulary in a fixed order so no language's map
// iteration order can leak into the output.

use std::collections::HashMap;

const CORPUS: u64 = 3_000_000;
const VOCAB: u64 = 64;

fn main() {
    let words: Vec<String> = (0..VOCAB).map(|i| format!("word{:02}", i)).collect();

    let mut counts: HashMap<String, u64> = HashMap::with_capacity(256);

    let mut state: u64 = 1;
    for _ in 0..CORPUS {
        state = (state * 48271) % 2147483647;
        let word = &words[(state % VOCAB) as usize];
        match counts.get_mut(word) {
            Some(count) => *count += 1,
            None => {
                counts.insert(word.clone(), 1);
            }
        }
    }

    let mut checksum: u64 = 0;
    for word in &words {
        let count = counts.get(word).copied().unwrap_or(0);
        checksum = (checksum * 31 + count) % 1_000_000_007;
    }
    println!("{}", checksum);
}
